SourceCode.Declaration:
/// <summary>
/// Design-time (build) class of <c>DEVTutorialArcadeControl</c>: adds "DEV Tutorial Arcade" to the form designer.
/// </summary>
[FormDesignControlAttribute("DEV Tutorial Arcade")]
class DEVTutorialArcadeControlBuild extends FormBuildControl
{
    DEVTutorialArcadeGame game;
}

Method.Source:
/// <summary>
/// Gets or sets the game shown when the form opens.
/// </summary>
/// <param name = "_game">The game.</param>
/// <returns>The game.</returns>
[FormDesignPropertyAttribute("Game", "Data")]
public DEVTutorialArcadeGame game(DEVTutorialArcadeGame _game = game)
{
    if (!prmIsDefault(_game))
    {
        game = _game;
    }

    return game;
}
